opencat.script:
var T = ctx.timeline();
var PARTICLES = ['p1','p2','p3','p4','p5','p6','p7','p8','p9','p10','p11','p12'];

// 0.0 - 1.5s: Aurora + spotlight bloom in
T.to('aurora', { opacity: 0.85, duration: 1.2, ease: 'power2.out' }, 0.0);
T.to('spot', { opacity: 1, duration: 1.4, ease: 'power2.out' }, 0.2);

// 0.2 - 3.0s: Particles twinkle in (staggered)
T.to(PARTICLES, { opacity: 0.85, duration: 0.8, stagger: { each: 0.06 }, ease: 'power2.out' }, 0.3);

// Each particle breathes over the remaining Act 4 duration
for (var i = 0; i < PARTICLES.length; i++) {
  var delay = 0.5 + (i % 5) * 0.4;
  var cycleDur = 2.0 + (i % 3) * 0.5;
  var totalLeft = 8.0 - delay;
  var repeats = Math.max(0, Math.floor(totalLeft / cycleDur) - 1);
  T.to(PARTICLES[i], {
    opacity: 0.3,
    y: '+=6',
    duration: cycleDur,
    ease: 'sine.inOut',
    repeat: repeats,
    yoyo: true,
  }, delay);
}

// 0.8 - 2.0s: Wordmark blur-to-sharp
T.to('w-hyper',  { opacity: 1, filter: 'blur(0px)', duration: 0.85, ease: 'power2.out' }, 0.9);
T.to('w-frames', { opacity: 1, filter: 'blur(0px)', duration: 0.85, ease: 'power2.out' }, 1.20);

// 2.4 / 3.3: promise lines
T.to('line-1', { opacity: 1, filter: 'blur(0px)', duration: 0.8, ease: 'power2.out' }, 2.4);
T.to('line-2', { opacity: 1, filter: 'blur(0px)', duration: 0.8, ease: 'power2.out' }, 3.3);

// 4.8 - 5.8s: install pill
T.to('install', { opacity: 1, duration: 0.5, ease: 'power2.out' }, 4.8);
T.to('install-cmd', { opacity: 1, filter: 'blur(0px)', duration: 0.8, ease: 'power2.out' }, 5.0);

// 6.0 - 8.0s: breath dot
T.fromTo('breath-dot', { opacity: 0, scale: 0 }, { opacity: 0.9, scale: 1.0, duration: 0.5, ease: 'back.out(2)' }, 6.0);
T.to('breath-dot', { scale: 1.5, opacity: 0.5, duration: 0.8, ease: 'sine.inOut', yoyo: true, repeat: 1 }, 6.5);

// Wordmark subtle breath through the whole composition
T.to(['w-hyper', 'w-frames'], {
  scale: 1.01, duration: 3.5, ease: 'sine.inOut', yoyo: true, repeat: 1, transformOrigin: '50% 50%',
}, 1.8);

// Aurora drifts
T.to('aurora', { x: 40, y: -20, duration: 7.5, ease: 'sine.inOut' }, 0.2);

// Master captions: rel 2.0 = "Give your agent a URL", rel 6.3 = "Go make something".
// Reference `.cap` runs the CSS `cap-pop` keyframes once (0.26s,
// cubic-bezier(0.34,1.56,0.64,1) applied per keyframe segment) and holds:
//   0%   opacity 0, y 18px, scale 0.82
//  70%   opacity 1, y -2px, scale 1.04
// 100%   opacity 1, y 0,    scale 1.00
var CAP_EASE = [0.34, 1.56, 0.64, 1];
function popCaption(id, at, dur) {
  T.set(id, { opacity: 0, y: 18, scale: 0.82 }, at);
  T.to(id, { opacity: 1, y: -2, scale: 1.04, duration: 0.182, ease: CAP_EASE }, at);
  T.to(id, { y: 0, scale: 1.0, duration: 0.078, ease: CAP_EASE }, at + 0.182);
  // Reference `.cap` is a timed clip: it vanishes when its VO window ends.
  T.set(id, { opacity: 0 }, at + dur);
}
// Master data-start/data-duration (index.html): cap1 35.80s/2.83s,
// cap2 40.10s/1.21s; act4 starts at abs 33.8s -> local 2.00s / 6.30s.
popCaption('cap1', 2.0, 2.83);
popCaption('cap2', 6.3, 1.21);
